{
  "scene_number": { "type": "nullable_number", "description": "The screenplay's own scene number this beat belongs to, e.g. 2 for \"2 INT. a location...\". Omit ONLY for pre-scene content with no scene heading at all (e.g. an opening title sequence/montage before scene 1) - never invent one.", "optional": true },
  "beat_number": { "type": "nullable_number", "description": "1-indexed position of this beat within its scene (resets to 1 at the start of each new scene). Omit if scene_number is also omitted.", "optional": true },
  "line_start": { "type": "number", "description": "First line number (from the provided numbered source text) belonging to this beat" },
  "line_end": { "type": "number", "description": "Last line number (from the provided numbered source text) belonging to this beat" },
  "scene_heading": { "type": "nullable_string", "description": "The verbatim scene slugline this beat belongs to, e.g. \"INT. a location - PRESENT DAY (2099)\". Omit for pre-scene content.", "optional": true },
  "int_ext": { "type": "nullable_string", "description": "One of INT, EXT, or INT/EXT, matching the scene heading. Omit for pre-scene content.", "optional": true },
  "location": { "type": "nullable_string", "description": "Normalized location name, e.g. \"a location\". Omit for pre-scene content.", "optional": true },
  "time_of_day": { "type": "nullable_string", "description": "Time of day from the scene heading, e.g. \"Present Day (2099)\", \"Day\", \"Night\", \"Continuous\". Omit if not specified.", "optional": true },
  "summary": { "type": "string", "description": "1-3 sentence prose description of what happens in this beat" },
  "characters": {
    "type": "array",
    "description": "Every character present in this beat, in order of significance",
    "items": {
      "name": { "type": "string", "description": "Character name exactly as written in the script (e.g. CHARACTER, not Clem Wellman)" },
      "presence": { "type": "string", "description": "Exactly one of: \"in_scene\" (physically present, visible on screen), \"voice_only\" (heard but never seen - phone call, V.O., intercom, radio), \"off_screen\" (present in the location but not shown - e.g. speaking from another room). This determines whether the character needs a visual reference generated, so classify carefully - do not default to in_scene." },
      "blocking": { "type": "nullable_string", "description": "What this character is doing / where positioned during this specific beat, e.g. \"seated at his desk, sits back once the interview ends\"", "optional": true }
    }
  },
  "objects": {
    "type": "array",
    "description": "Physical objects/props present or interacted with in this beat",
    "items": {
      "name": { "type": "string", "description": "The object's name" },
      "notes": { "type": "nullable_string", "description": "Brief note on how it's used or where it is in this beat", "optional": true }
    }
  },
  "dialogue": {
    "type": "array",
    "description": "Every line of dialogue spoken in this beat, in order",
    "items": {
      "character": { "type": "string", "description": "Speaking character's name exactly as written in the script" },
      "parenthetical": { "type": "nullable_string", "description": "Any parenthetical direction before the line, e.g. \"beat, then defiantly\". Omit if none.", "optional": true },
      "line": { "type": "string", "description": "The verbatim dialogue line, without surrounding quote marks" }
    }
  }
}

